    "usage": {
      "anatomy": [
        {
          "name": "Document",
          "required": true,
          "description": "Root container for block or inline Markdown content."
        },
        {
          "name": "Heading",
          "required": false,
          "description": "Rendered semantic heading block; a custom heading renderer replaces the built-in part."
        },
        {
          "name": "Paragraph",
          "required": false,
          "description": "Rendered paragraph block; a custom paragraph renderer replaces the default part."
        },
        {
          "name": "List",
          "required": false,
          "description": "Ordered, unordered, or task-list block rendered from Markdown items."
        },
        {
          "name": "Code block",
          "required": false,
          "description": "Fenced code block; long lines wrap rather than scroll sideways. A custom code renderer replaces the default part."
